async function ensureDock(){return dockPromise??=(async()=>{status('Preparando os painéis de trabalho…');const lib=await libraries();dock=lib.createDockview($('dock'),{createComponent:()=>new Panel({contexts,panels,activate:setActive,controlsChanged:updateHeader,open:openPanel,preview:previewSave,error,close:closePanel,task:openTask,navigate,changed:changedData,source:openSourceById,getDocument:(ctx,lang)=>documentContext({id:ctx.id},lang,ctx.project),language:async(ctx,lang,type)=>{const other=await documentContext({id:ctx.id},lang,ctx.project);try{sessionStorage.setItem('studio:language:'+ctx.id,lang);}catch{}await openPanel(type,other);},passage:(ctx,block,selection)=>documents.passage(ctx,block,selection),cite:(ctx,block)=>documents.cite(ctx,block),sourceIds:project=>projectInfo(project)?.source_ids}),createTabComponent:()=>new Tab(),defaultTabComponent:'studio',theme:{name:'studio',className:'dockview-theme-light',gap:4},defaultRenderer:'always'});dock.onDidActivePanelChange(panel=>{if(panel)setActive(contexts.get(panel.params.key));});dock.onDidLayoutChange(()=>{clearTimeout(layoutTimer);layoutTimer=setTimeout(persistLayout,400);});return dock;})();}
function canClosePanel(id){const panel=dock?.getPanel(id),host=panels.get(id),ctx=panel&&contexts.get(panel.params.key);if(host?.task?.isSaving()||host?.viewerControl?.isSaving()||ctx?.saving||catalogBusy){error('Aguarde a gravação.');return false;}if(host?.task&&!host.task.canClose()&&!confirm('Descartar os campos ainda não salvos desta tarefa?'))return false;if(ctx?.dirty&&!confirm('O rascunho está guardado nesta sessão. Fechar este painel?'))return false;return true;}
