class Tab{constructor(){this.element=node('div',{class:'studio-tab'});}init(args){const close=node('button',{type:'button',text:'×','aria-label':'Fechar '+args.title});close.onclick=e=>{e.stopPropagation();closePanel(args.api.id);};const label=node('span',{text:args.title});this.element.append(label,close);this.titleListener=args.api.onDidTitleChange(event=>{label.textContent=event.title;close.setAttribute('aria-label','Fechar '+event.title);});}dispose(){this.titleListener?.dispose();}}

function setActive(ctx){if(!ctx)return;const changed=active!==ctx;active=ctx;if(ctx.kind!=='task')lastMaterial=ctx;ctx.dispatchEvent(new Event('focus'));$('landing').hidden=true;$('library').hidden=true;$('work').hidden=false;updateHeader();if(area==='sources'&&!listSources)renderExplorer();if(changed&&toolKey&&toolKey!=='metrics'){closeTool();}schedulePoll();}
function updateHeader(){if(!active)return;const ctx=active;$('work-title').textContent=ctx.name;$('work-title').title=ctx.name;$('work-kind').textContent=ctx.kind==='source'?'FONTE / PÁGINA':ctx.kind==='task'?'INSTRUMENTO':'DOCUMENTO / '+ctx.lang.toUpperCase();$('scope').textContent=ctx.project?(ctx.kind==='source'?'Fonte local · ':'Privado · ')+(projectInfo(ctx.project)?.title||ctx.project):(ctx.kind==='source'?'Fonte local':'Acervo local');$('page-control').hidden=ctx.kind!=='source';$('work-actions').hidden=ctx.kind==='task';$('doc-language-wrap').hidden=ctx.kind!=='document';if(ctx.kind==='document'){const codes=[...new Set([...(ctx.info?.editions||[]).map(e=>e.language),...(ctx.project?['pt','en']:[])])];$('doc-language').replaceChildren(...codes.map(code=>node('option',{value:code,text:code.toUpperCase()})));$('doc-language').value=ctx.lang;}$('page-number').value=ctx.page||1;$('page-number').max=ctx.count||1;$('page-total').textContent='/ '+(ctx.count||'—');$('candidate-count').textContent=ctx.review?.candidates?.length||0;for(const b of document.querySelectorAll('#work-actions [data-action]'))b.hidden=ctx.kind!=='source'&&['ocr','candidates','image','cite','incorporate','alignment','book','pdf-tools','publication'].includes(b.dataset.action);for(const b of document.querySelectorAll('[data-doc-only]'))b.hidden=ctx.kind!=='document';for(const b of document.querySelectorAll('[data-source-only]'))b.hidden=ctx.kind!=='source';for(const b of document.querySelectorAll('[data-public-only]'))b.hidden=!!ctx.project;for(const b of document.querySelectorAll('[data-project-only]'))b.hidden=!ctx.project;$('save').disabled=ctx.removed||ctx.saving||(ctx.kind==='source'?!ctx.review:ctx.format!=='markdown'||ctx.snapshot?.archived);$('save').textContent=ctx.saving?'Gravando…':ctx.dirty?'Conferir e salvar ●':'Conferir e salvar';status(ctx.saving?'Gravação em andamento; não feche o backend.':ctx.dirty?'Rascunho nesta sessão · alterações ainda não confirmadas':ctx.error||'Pronto · '+(ctx.project?'versão privada do projeto':'trabalho local'));syncReadingControls();}
function syncReadingControls(){const host=$('studio-reading-controls'),panel=dock?.activePanel?panels.get(dock.activePanel.id):null;host.replaceChildren();const viewerHost=$('studio-viewer-controls'),book=dock?.activePanel?.params.type==='book';viewerHost.replaceChildren();viewerHost.hidden=!book;document.body.classList.toggle('bookreader-active',book);$('tool-toggle').hidden=book;const pair=document.querySelector('.view-menu [data-layout="pair"]');if(pair)pair.hidden=book;for(const action of ['read','details','download','export']){const b=document.querySelector('.view-menu [data-action="'+action+'"]');if(b)b.hidden=book;}const available=active?.kind==='document'&&panel?.ctx===active&&panel?.readingSurface;host.hidden=!available;if(available){host.append(panel.readingSurface.controls);if(!active.dirty&&!active.saving)status(panel.readingSurface.state().message);$('doc-language-wrap').hidden=true;for(const b of document.querySelectorAll('#work-actions [data-action="study"],#work-actions [data-action="parallel"]'))b.hidden=true;}if(book){$('page-control').hidden=true;$('work-actions').hidden=true;$('doc-language-wrap').hidden=true;host.hidden=true;$('work-kind').textContent='LEITOR DE PDF';for(const b of document.querySelectorAll('.view-menu [data-action]'))b.hidden=true;if(toolKey&&!catalogBusy)closeTool();if(panel?.viewerControl){viewerHost.append(panel.viewerControl.controls);const info=panel.viewerControl.state();$('work-title').textContent=info.title;$('work-title').title=info.title;status(info.message);}else{viewerHost.append(node('span',{class:'slim',text:'Preparando BookReader…'}));$('work-title').textContent='BookReader';} $('scope').textContent=active?.project?'Consulta · '+(projectInfo(active.project)?.title||active.project):'Consulta de PDF';}}
function attach(ctx){contexts.set(ctx.key,ctx);ctx.addEventListener('page',()=>{if(active===ctx&&['candidates','history','details','cite','save'].includes(toolKey))closeTool();dock?.getPanel(ctx.key+':diff')?.api.close();});ctx.addEventListener('change',()=>{if(active===ctx)updateHeader();});ctx.addEventListener('edited',()=>{if(active===ctx)updateHeader();});ctx.addEventListener('inventory',()=>{if(active===ctx&&area==='sources'&&!listSources)renderExplorer();});ctx.addEventListener('loaded',()=>{if(active===ctx&&area==='sources'&&!listSources)renderExplorer();});}
async function openPanel(type,ctx=active,direction){if(!ctx)throw Error('Escolha um material.');if(catalogBusy)throw Error('Aguarde a gravação.');setActive(ctx);await ensureDock();const baseId=ctx.key+':'+type;let id=baseId,panel=dock.panels.find(p=>p.params.key===ctx.key&&p.params.type===type);if(panel){panel.api.setActive();return panel;}while(dock.getPanel(id))id=baseId+':view-'+(++viewSerial);const label={study:'Estudo por parágrafo',parallel:'Estudo paralelo',book:'BookReader',print:'Edição PDF','zoom-image':'Imagem ampliável',source:'Fac-símile',text:ctx.kind==='source'?'Transcrição':'Markdown',read:'Leitura',diff:'Conferência',image:'Imagem derivada'}[type];panel=dock.addPanel({id,component:'document',title:label+' · '+ctx.name,params:{key:ctx.key,type},renderer:'always',...(direction&&dock.activePanel?{position:{referencePanel:dock.activePanel.id,direction}}:{})});return panel;}
async function switchDocumentView(type,ctx=material()){if(ctx?.kind!=='document')throw Error('Abra um documento.');const candidates=[...panels.values()].filter(p=>!p.dead&&p.ctx===ctx&&['read','study','parallel'].includes(p.args?.params.type)),panel=candidates.find(p=>p.args.api.id===dock.activePanel?.id)||candidates[0];if(!panel)return openPanel(type,ctx);await panel.ready;if(panel.dead)return;panel.args.api.setActive();if(!panel.readingSurface)throw Error('A vista não foi carregada. Use Tentar novamente nesta aba.');await panel.readingSurface.setMode(type);}
