async function documentContext(info,language,project=selectedProject){if(project&&!projectInfo(project)?.document_ids.includes(info.id))throw Error('Este documento não está vinculado ao projeto selecionado. Abra sem projeto ou vincule-o no gerenciamento de projetos.');if(!language){const data=await request('/api/editorial/documents/'+encodeURIComponent(info.id));let preferred;try{preferred=sessionStorage.getItem('studio:language:'+info.id);}catch{}language=data.editions.some(e=>e.language===preferred)?preferred:data.editions.some(e=>e.language==='pt')?'pt':data.editions[0]?.language||'ru';}const key='document:'+project+':'+info.id+':'+language,existing=contexts.get(key);if(existing?.snapshot)return existing;if(documentLoads.has(key))return documentLoads.get(key);const pending=(async()=>{const data=await request('/api/editorial/documents/'+encodeURIComponent(info.id)),ctx=existing||new Document({...data.document,editions:data.editions},language,project);if(!existing)attach(ctx);await ctx.initialize();return ctx;})();documentLoads.set(key,pending);try{return await pending;}finally{documentLoads.delete(key);}}
async function openDocument(info,language,project=selectedProject){const ctx=await documentContext(info,language,project);setActive(ctx);await openPanel('read',ctx);return ctx;}
async function openSourceById(id,page,project=selectedProject){const info=await request('/api/editorial/pdf/'+encodeURIComponent(id));await openSource(info,project);const ctx=contexts.get('source:'+project+':'+id);if(page)await ctx.selectPage(Number(page));return ctx;}
function material(){if(dock?.activePanel?.params.type==='book')return null;return active?.kind==='task'?contexts.get(active.contextKey)||lastMaterial:active;}
async function openTask(route,label='Tarefa editorial',context=material(),advanced=null){if(catalogBusy)throw Error('Aguarde a gravação.');if(route==='pdf/novo'){selectPdf(context?.project||selectedProject);return;}if(/^pdf\/pdf-[a-f0-9]{32}(?:\?|$)/.test(route)){const [id,query='']=route.slice(4).split('?');return openSourceById(id,new URLSearchParams(query).get('pagina'),context?.project||'');}const params=new URLSearchParams(route.split('?')[1]||'');params.sort();route=route.split('?')[0]+(params.size?'?'+params:'');const project=advanced?context?.project||'':'',key='task:'+project+':'+(advanced||route)+':'+(advanced?context?.key+':'+(context?.page||''):'');let ctx=contexts.get(key);if(!ctx){ctx=Object.assign(new EventTarget(),{kind:'task',id:key,key,name:label,project,contextKey:context?.key||'',dirty:false,text:''});contexts.set(key,ctx);}setActive(ctx);await ensureDock();const id=ctx.key+':task';let panel=dock.getPanel(id);if(panel){panel.api.setActive();return panel;}const options={route:advanced||route,label,project,contextKey:context?.key||'',sourceId:context?.kind==='source'?context.id:'',documentId:context?.kind==='document'?context.id:'',page:context?.page||1};return dock.addPanel({id,component:'document',title:label,params:{key:ctx.key,type:advanced?'source-task':'task',options},renderer:'always'});}
async function changedData(data={}){try{await refreshProjects();if(data.path?.endsWith('/activate')){selectedProject=data.active_id||'';$('project').value=selectedProject;}await loadSources();if(data.document_id){for(const ctx of contexts.values())if(ctx.kind==='document'&&ctx.id===data.document_id){if(ctx.dirty){ctx.error='Há uma versão salva mais recente. O rascunho foi preservado; compare antes de substituir.';if(active===ctx)updateHeader();}else if(data.document_exists===false){ctx.removed=true;ctx.error='Documento retirado do catálogo por uma restauração. O texto aberto continua disponível para recuperação.';}else await ctx.initialize();}}}catch(errorValue){error('A alteração foi salva; atualize a lista: '+errorValue.message);}}
async function refreshProjects(){const data=await request('/api/editorial/projects');projects=data.items;const chosen=selectedProject;$('project').replaceChildren(node('option',{value:'',text:'Acervo · sem projeto'}),...projects.filter(p=>!p.archived).map(p=>node('option',{value:p.id,text:p.title})));selectedProject=projects.some(p=>p.id===chosen&&!p.archived)?chosen:'';$('project').value=selectedProject;}
async function navigate(href){const target=new URL(href,location.origin),hash=target.hash;if(!hash.startsWith('#/')){if(target.pathname==='/')location.href=target.href;return;}const [path,raw='']=hash.slice(2).split('?'),params=new URLSearchParams(raw),project=params.get('projeto')||'';if(params.get('leitor')){try{const back=new URL(params.get('leitor'),location.origin);if(back.origin===location.origin&&back.pathname==='/'){$('portal-link').href=back.href;$('portal-link').textContent='Voltar à leitura';}}catch{}}if(path.startsWith('doc/')){const ctx=await openDocument({id:decodeURIComponent(path.slice(4))},params.get('idioma'),project);if(params.get('editar')==='1')await openPanel('text',ctx,'right');const token=params.get('trecho');if(token){let incoming;try{incoming=JSON.parse(sessionStorage.getItem('portal:passage:'+token));}catch{}if(!incoming||project||incoming.document_id!==ctx.id||incoming.language!==ctx.lang)throw Error('O trecho transportado não corresponde a esta versão.');const body=await documents.body(ctx.original),sha=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(body)))).map(n=>n.toString(16).padStart(2,'0')).join('');if(sha!==incoming.sha256)throw Error('A versão mudou desde o estudo. Reabra o trecho antes de corrigir.');await openPanel('study',ctx);await documents.passage(ctx,incoming.block,incoming.selection);sessionStorage.removeItem('portal:passage:'+token);}return ctx;}if(path==='bancada'){if(project){await refreshProjects();selectedProject=project;$('project').value=project;}return chooseArea('sources');}if(path.startsWith('colecao/')){const parts=path.split('/');catalogFilter=parts[1]+(parts[2]==='subcolecao'?'/'+parts[3]:'');return chooseArea('catalog');}if(path==='busca')return chooseArea('catalog');if(path==='pdf'||path.startsWith('pdf/')){if(path==='pdf')return chooseArea('sources');if(path==='pdf/novo'){selectPdf(project);return;}if(path==='pdf/ferramentas')return openTask('pdf/ferramentas','Manipular PDF',{kind:'source',id:params.get('fonte')||'',project},'pdf-tools');return openSourceById(path.slice(4),params.get('pagina'),project);}if(path==='markdown'||path.startsWith('markdown/')){const edition=decodeURIComponent(path.slice(9)),split=edition.lastIndexOf(':'),id=path==='markdown'?params.get('documento'):decodeURIComponent(split>=0?edition.slice(0,split):edition);if(id){const ctx=await documentContext({id},split>=0?decodeURIComponent(edition.slice(split+1)):params.get('idioma'),project);const token=params.get('rascunho');if(token)try{const draft=JSON.parse(sessionStorage.getItem('workspaceDraft:v1:'+token));if(draft?.document_id===ctx.id&&draft.language===ctx.lang&&draft.baseline_sha256===ctx.snapshot.edition?.sha256){ctx.edit(draft.content);ctx.emit('loaded');sessionStorage.removeItem('workspaceDraft:v1:'+token);}}catch{}return openPanel('text',ctx);}}if(path==='importar'&&project){const ctx=await documentContext({id:params.get('documento')},params.get('idioma')||'pt',project);return documents.import(ctx);}return openTask(path+(raw?'?'+raw:''),({catalogo:'Catálogo e metadados',fila:'Fila de revisão',historico:'Histórico',importar:'Importar tradução',lote:'Importar corpus','novo-documento':'Novo documento',projetos:'Projetos de pesquisa','projetos/novo':'Novo projeto'})[path]||'Edição do acervo',null);}

function home(){if(catalogBusy){error('Aguarde a gravação.');return;}if(!dock?.panels.length){active=null;lastMaterial=null;listSources=true;document.body.classList.remove('bookreader-active');$('studio-viewer-controls').replaceChildren();$('studio-viewer-controls').hidden=true;renderExplorer();}clearTimeout(pollTimer);$('landing').hidden=false;$('library').hidden=true;$('work').hidden=true;closeTool();document.body.classList.remove('focused');$('focus').textContent='Concentrar';status('As abas permanecem abertas. Escolha um material para continuar.');}
function library(heading,subtitle){if(catalogBusy)throw Error('Aguarde a gravação.');closeTool();clearTimeout(pollTimer);$('landing').hidden=true;$('work').hidden=true;$('library').hidden=false;$('library-title').textContent=heading;$('library-subtitle').textContent=subtitle;const host=node('div',{class:'library-body'});$('library-content').replaceChildren(host);return host;}
const catalog=new CatalogTools({library,tool:async(key,label)=>{const host=await openTool(key);$('tool-title').textContent=label;return host;},toolVersion:()=>toolVersion,context:setActive,busy:value=>{catalogBusy=value;},status,error,task:openTask,advanced:(route,label,ctx)=>openTask(route,label,ctx,route),updated:loadSources,openDocument,browse:async id=>{catalogFilter=id;await chooseArea('catalog');},actions:(...buttons)=>{$('tool-actions').replaceChildren(...buttons);$('tool-actions').hidden=!buttons.length;},close:closeTool});
const documents=new DocumentTools({tool:openTool,toolVersion:()=>toolVersion,open:openPanel,task:openTask,preview:previewSave,proposal:showSave,error,close:closeTool,status,changed:changedData,busy:value=>catalogBusy=value,compare:async(ctx,before,after)=>{ctx.previewBefore=before;ctx.previewText=after;dock?.getPanel(ctx.key+':diff')?.api.close();await openPanel('diff',ctx,'right');},actions:(...buttons)=>{$('tool-actions').replaceChildren(...buttons);$('tool-actions').hidden=!buttons.length;}});
function taskBoard(){const host=library('Pesquisa e edição','Cadastros, revisão, traduções e fontes no mesmo ambiente.'),groups=[['Acervo',[['novo-documento','Novo documento','Receber texto original e seus metadados.'],['lote','Importar corpus','Arquivos e metadados comuns com conferência guiada.'],['catalogo','Catálogo e metadados','Editar fichas e associações do acervo.']]],['Traduções e revisão',[['importar','Importar tradução','Selecionar documento/idioma e comparar antes de salvar.'],['fila','Fila de revisão','Prioridades, motivos e decisões editoriais.'],['historico','Histórico e recuperação','Rever e restaurar alterações com prévia.']]],['Projetos e instrumentos',[['projetos','Projetos de pesquisa','Gerenciar documentos, fontes e versões privadas.'],['projetos/novo','Novo projeto','Criar um contexto de investigação.'],['pdf/ferramentas','Manipular PDF','Extrair/dividir com proveniência e retomada.']]]];for(const [label,items]of groups){host.append(node('h2',{class:'library-section-title',text:label}));const grid=node('div',{class:'collection-grid'});for(const [route,title,description]of items){const card=node('article',{class:'collection-card'});card.append(node('h2',{text:title}),node('p',{text:description}),button('Abrir',()=>route==='pdf/ferramentas'?openTask(route,title,material(),'pdf-tools'):route==='importar'&&material()?.kind==='document'?documents.import(material()):openTask(route,title,material()),'accent'));grid.append(card);}host.append(grid);}host.append(node('div',{class:'card-actions'},[button('BookReader · fac-símiles',()=>utility('book','Leitor de fac-símiles')),button('Imagem ampliável',()=>utility('zoom-image','Examinar imagem')),button('Retomar composição da sessão',resumeLayout)]));}
async function utility(type,label){const key='utility:'+type+':'+selectedProject;let ctx=contexts.get(key);if(!ctx){ctx=Object.assign(new EventTarget(),{kind:'task',key,id:key,name:label,project:selectedProject,text:'',dirty:false});contexts.set(key,ctx);}await openPanel(type,ctx);}
function persistLayout(){if(!dock||restoring)return;try{const required=new Set(dock.panels.flatMap(p=>[p.params.key,p.params.options?.contextKey].filter(Boolean)));const descriptors=[...contexts.values()].filter(ctx=>required.has(ctx.key)).map(ctx=>({key:ctx.key,kind:ctx.kind,id:ctx.id,lang:ctx.lang,project:ctx.project,name:ctx.name,contextKey:ctx.contextKey,page:ctx.page}));sessionStorage.setItem('studio:layout:v2',JSON.stringify({layout:dock.toJSON(),contexts:descriptors}));}catch{status('Não foi possível guardar a composição. Rascunhos continuam disponíveis para download.');}}
async function resumeLayout(){let saved;try{saved=JSON.parse(sessionStorage.getItem('studio:layout:v2'));}catch{}if(!saved?.layout)throw Error('Não há composição de sessão para retomar.');if(dock?.panels.length&&!dock.panels.every(p=>canClosePanel(p.id)))return;const privateCount=saved.contexts.filter(c=>c.project).length;if(privateCount&&!confirm('Retomar a composição inclui '+privateCount+' materiais vinculados a projetos privados. Cada aba manterá seu contexto. Continuar?'))return;restoring=true;try{for(const item of saved.contexts){if(item.project&&!projectInfo(item.project))continue;if(item.kind==='document')await documentContext({id:item.id},item.lang,item.project||'');else if(item.kind==='source'){const ctx=contexts.get(item.key)||new Source(await request('/api/editorial/pdf/'+item.id),item.project||'');if(!contexts.has(item.key))attach(ctx);await ctx.initialize();if(item.page)await ctx.selectPage(item.page);}else if(!contexts.has(item.key))contexts.set(item.key,Object.assign(new EventTarget(),item,{text:'',dirty:false}));}await ensureDock();if(saved.contexts.some(c=>!contexts.has(c.key)))throw Error('Um projeto da composição não está mais disponível. Reabra os materiais existentes pelo explorador.');dock.fromJSON(saved.layout);if(dock.activePanel)setActive(contexts.get(dock.activePanel.params.key));status('Composição retomada; destinos de cada aba preservados.');}finally{restoring=false;}}
