async function citeTool(host,ctx){needSource(ctx);if(!ctx.review)throw Error('Aguarde a transcrição da página.');const saved=ctx.review.review,quote=ctx.dirty?'':ctx.selection||'',unit=(saved.units||[]).find(u=>Array.from(saved.text).slice(u.start,u.end)===quote);const citation=ctx.name+' · fonte '+ctx.id+' · página física '+ctx.page+(saved.printed_label?' · rótulo '+saved.printed_label:'')+' · revisão '+ctx.review.revision+(unit?' · unidade '+unit.id+' · SHA-256 '+unit.sha256:'');message(host,ctx.dirty?'A referência abaixo é da revisão salva, não do rascunho. Salve para citar o trecho editado.':'A página física e o rótulo registrado são mantidos separados. Uma unidade é identificada quando a seleção coincide com seus limites salvos.');host.append(node('pre',{class:'diff-text',text:citation}),button('Copiar referência',()=>navigator.clipboard.writeText(citation),'accent'));if(quote)host.append(node('blockquote',{text:quote}));}
function notesTool(host,ctx){const key='studio:notes:'+(ctx?.key||selectedProject||'geral'),input=node('textarea',{class:'note-pad','aria-label':'Notas privadas da sessão'});try{input.value=sessionStorage.getItem(key)||'';}catch{}input.oninput=()=>{try{sessionStorage.setItem(key,input.value);}catch{error('Não foi possível guardar as notas. Baixe uma cópia.');}};message(host,'Notas da sessão, separadas dos textos do acervo.');host.append(input,button('Baixar notas',()=>download((ctx?.id||'pesquisa')+'.notas.md',input.value)));}
async function jobsTool(host,ctx,cached=false){if(ctx?.kind!=='source'){message(host,'Abra uma fonte para consultar os lotes de OCR.');return;}const source=ctx;if(!cached)await source.overview();if(toolKey!=='jobs'||active!==source)return;host.replaceChildren();message(host,'O processamento continua no backend enquanto você consulta ou revisa outras páginas.');for(const job of source.jobs){const card=node('article',{class:'tool-card'}),done=job.completed_pages.length,total=job.recipe.pages.length;card.append(node('h3',{text:({queued:'Na fila',running:'Em processamento',completed:'Concluído',interrupted:'Interrompido',failed:'Falhou'}[job.state]||job.state)+' · '+done+'/'+total}),node('progress',{max:total,value:done}),node('p',{text:job.recipe.languages.join('+')+' · '+job.recipe.dpi+' DPI · '+job.recipe.pages.length+' páginas'}));if(job.error)card.append(node('p',{class:'error',text:job.error}));if(['failed','interrupted'].includes(job.state))card.append(button('Retomar restantes',async()=>{await request('/api/editorial/pdf/ocr/resume',{body:{job_id:job.id}});await openTool('jobs');schedulePoll();}));if(job.state==='completed')card.append(button('Revisar primeira página do lote',async()=>{await source.selectPage(job.recipe.pages[0]);await openPanel('text',source);await openTool('candidates');}));host.append(card);}if(!source.jobs.length)message(host,'Nenhum lote OCR para esta fonte.');}
function metricsTool(host){message(host,'Tempos das últimas consultas deste protótipo. Bibliotecas são carregadas sob demanda; não há varredura global de DOM nem adaptação da interface anterior.');for(const entry of timings)host.append(node('div',{class:'metrics-row',text:entry.ms+' ms · HTTP '+entry.status+'\n'+entry.path}));host.append(button('Atualizar diagnóstico',()=>openTool('metrics')));}
function helpTool(host){message(host,'Comece com uma fonte: a imagem e a transcrição abrem em dois painéis sincronizados pela página. Arraste as abas para as bordas para mudar a composição.');for(const t of ['OCR gera candidatos; carregar um candidato não salva automaticamente.','Conferir e salvar abre uma comparação e pede confirmação.','O projeto escolhido acompanha o material aberto. Ele não altera retroativamente as outras abas. Recarregar começa sem projeto.','Concentrar recolhe o entorno; Escape restaura. Ctrl K abre os comandos.','O ensaio de imagem usa um worker e permite baixar uma prévia e sua receita. Ainda não alimenta o OCR.','Use Pesquisa e edição para metadados, novos documentos, corpus, importação de tradução, fila e histórico. Projetos e ferramentas da fonte abrem em abas do Estúdio.'])host.append(node('p',{class:'tool-callout',text:t}));}
function fingerprint(ctx){return JSON.stringify([ctx.page,ctx.text,ctx.status,ctx.printed,ctx.notes,ctx.basis]);}
async function previewSave(ctx=active){if(dock?.activePanel?.params.type==='book')throw Error('Abra Revisão / OCR antes de salvar uma transcrição.');if(!ctx)throw Error('Abra um material.');const before=fingerprint(ctx),p=await ctx.preview();if(before!==fingerprint(ctx))throw Error('O texto mudou durante a prévia. Confira novamente.');await showSave(ctx,p);}
async function showSave(ctx,p){const signature=fingerprint(ctx);ctx.previewBefore=ctx.kind==='source'?ctx.review.review.text:ctx.original;ctx.previewText=p.after?.text??p.content??p.markdown_edit?.content??ctx.text;dock.getPanel(ctx.key+':diff')?.api.close();await openPanel('diff',ctx,'right');const host=await openTool('save');message(host,ctx.project&&ctx.kind==='document'?'Confirmação de versão privada: salvar não substitui o acervo.':'Confirmação de gravação local. O histórico anterior será preservado.');if(p.warnings?.length)host.append(node('pre',{class:'diff-text',text:JSON.stringify(p.warnings,null,2)}));if(p.before)host.append(node('p',{class:'tool-callout',text:'Estado: '+p.before.status+' → '+p.after.status+' · Rótulo: '+(p.before.printed_label||'—')+' → '+(p.after.printed_label||'—')}));if(p.before)host.append(node('details',{},[node('summary',{text:'Notas e base da transcrição'}),node('pre',{class:'diff-text',text:JSON.stringify({antes:{notes:p.before.notes,basis:p.before.basis},depois:{notes:p.after.notes,basis:p.after.basis}},null,2)})]));const confirm=button('Confirmar gravação local',async()=>{if(signature!==fingerprint(ctx))throw Error('O rascunho ou a página mudou. Prepare outra prévia.');confirm.disabled=true;try{await ctx.save(p);if(active===ctx&&toolKey==='save')closeTool();status('Salvo localmente com histórico.');}catch(e){confirm.disabled=false;throw e;}},'accent');if(p.warnings?.length){const ack=node('input',{type:'checkbox'});confirm.disabled=true;ack.onchange=()=>confirm.disabled=!ack.checked;host.append(node('label',{class:'tool-field'},[ack,' Li as divergências e quero confirmar esta versão.']));}$('tool-actions').append(confirm,button('Continuar editando',async()=>{closeTool();await openPanel('text',ctx);}));$('tool-actions').hidden=false;host.append(node('p',{class:'slim',text:'Não faz commit, push ou publicação automática.'}));}
function schedulePoll(){clearTimeout(pollTimer);const ctx=active;if(ctx?.kind!=='source'||dock?.activePanel?.params.type==='book'||document.hidden||$('work').hidden)return;const inventory=['queued','running'].includes(ctx.data.state),jobs=ctx.jobs.some(j=>['queued','running'].includes(j.state));if(!inventory&&!jobs)return;pollTimer=setTimeout(async()=>{try{if(active!==ctx||document.hidden)return;if(inventory){await ctx.refresh();if(!ctx.review&&ctx.data.pages?.some(p=>p.page_number===ctx.page))await ctx.selectPage(ctx.page);}if(jobs){await ctx.overview();if(toolKey==='jobs')await jobsTool($('tool-body'),ctx,true);} }catch(e){error(e);}finally{if(active===ctx)schedulePoll();}},3000);}
const commands=[['Pesquisa e edição',()=>chooseArea('editorial')],['Gerenciar projetos',()=>chooseArea('projects')],['Novo projeto',()=>openTask('projetos/novo','Novo projeto',null)],['Novo documento',()=>openTask('novo-documento','Novo documento')],['Importar corpus',()=>openTask('lote','Importar corpus')],['Fila de revisão',()=>openTask('fila','Fila de revisão')],['Importar tradução',()=>documents.import(material())],['Estudo por parágrafo',()=>action('study')],['Estudo paralelo',()=>action('parallel')],['Retomar composição',resumeLayout],['Adicionar PDF',()=>selectPdf()],['Fontes',()=>chooseArea('sources')],['Coleções',()=>chooseArea('collections')],['Nova coleção',()=>catalog.createCollection()],['Vincular coleção',()=>catalog.classify(material())],['Criar documento da transcrição',()=>catalog.incorporate(material())],['Pesquisar acervo',()=>chooseArea('catalog')],['Gerar OCR',()=>action('ocr')],['Candidatos OCR',()=>action('candidates')],['Ensaio de imagem',()=>openPanel('image',active,'right')],['Histórico',()=>action('history')],['Conferir e salvar',()=>previewSave()],['Notas de pesquisa',()=>openTool('notes')],['Fonte e texto lado a lado',()=>pair()],['Diagnóstico de carregamento',()=>openTool('metrics')]];
function palette(){const draw=()=>{$('command-results').replaceChildren(...commands.filter(([label])=>label.toLocaleLowerCase().includes($('command-query').value.toLocaleLowerCase())).map(([label,fn])=>button(label,()=>{$('commands').close();return fn();})));};$('command-query').value='';$('command-query').oninput=draw;draw();$('commands').showModal();$('command-query').focus();}
async function action(key){if(dock?.activePanel?.params.type==='book'&&key!=='book')throw Error('No BookReader, use Revisão / OCR para trabalhar na fonte que está sendo lida.');const ctx=material();if(key==='metadata'){if(!ctx||ctx.kind!=='document')throw Error('Abra um documento.');return openTask('documento/'+ctx.id,'Metadados do acervo',ctx);}if(key==='translation')return documents.import(ctx);if(key==='promotion')return documents.promote(ctx);if(key==='links')return openTask('links','Documentos e fac-símiles',ctx,'links');if(key==='publication'&&ctx?.project)throw Error('A preparação pública de fac-símiles exige abrir a fonte sem projeto.');if(key==='publication')return openTask('publication','Fac-símiles estáticos',ctx,'publication');if(key==='alignment'){needSource(ctx);return openTask('alignment','Fronteiras e localização · p.'+ctx.page,ctx,'alignment');}if(key==='pdf-tools')return openTask('pdf/ferramentas','Manipular PDF',ctx,'pdf-tools');if(key==='history'&&ctx?.kind==='document')return documents.history(ctx);if(['study','parallel'].includes(key))return switchDocumentView(key,ctx);if(key==='print'){if(ctx?.kind!=='document')throw Error('Abra um documento do acervo.');return openPanel(key,ctx);}if(key==='book')return ctx?.kind==='source'?openPanel('book',ctx):utility('book','Leitor de fac-símiles');if(key==='export')return documents.export(ctx);if(key==='classify')return catalog.classify(ctx);if(key==='incorporate')return catalog.incorporate(ctx);if(key==='read')return openPanel('read',ctx);if(key==='download'){if(!ctx)throw Error('Abra um material.');return download(ctx.id+'.'+(ctx.lang||'ru')+'.rascunho.md',ctx.text);}if(key==='image'){needSource(ctx);return openPanel('image',ctx,'right');}if(['ocr','candidates','cite'].includes(key)&&ctx?.kind==='source'){setActive(ctx);return openTool(key);}return openTool(key);}

for(const b of document.querySelectorAll('[data-area]'))b.onclick=()=>chooseArea(b.dataset.area).catch(error);
for(const b of document.querySelectorAll('[data-action]'))b.onclick=()=>action(b.dataset.action).catch(error);
for(const b of document.querySelectorAll('[data-layout]'))b.onclick=async()=>{try{document.querySelector('.view-menu').open=false;if(b.dataset.layout==='pair')await pair();else if(b.dataset.layout==='close'){if(dock?.activePanel)closePanel(dock.activePanel.id);}else if(dock?.activePanel){if(dock.activePanel.group.api.isMaximized())dock.exitMaximizedGroup();else dock.activePanel.group.api.maximize();}}catch(e){error(e);}};
$('doc-language').onchange=async()=>{try{sessionStorage.setItem('studio:language:'+active.id,$('doc-language').value);const ctx=await documentContext({id:active.id},$('doc-language').value,active.project);await openPanel('read',ctx);}catch(e){error(e);}};$('resume-session').onclick=()=>resumeLayout().catch(error);$('save').onclick=()=>previewSave().catch(error);$('previous').onclick=()=>active?.selectPage(active.page-1).catch(error);$('next').onclick=()=>active?.selectPage(active.page+1).catch(error);$('page-number').onchange=()=>active?.selectPage(Number($('page-number').value)).catch(error);
$('focus').onclick=()=>{const focused=document.body.classList.toggle('focused');$('focus').textContent=focused?'Restaurar entorno':'Concentrar';$('focus').setAttribute('aria-pressed',String(focused));};$('explorer-toggle').onclick=()=>{const collapsed=document.body.classList.toggle('no-explorer');$('explorer-toggle').setAttribute('aria-expanded',String(!collapsed));$('explorer-toggle').textContent=collapsed?'›':'‹';};$('explorer-refresh').onclick=()=>loadSources().catch(error);$('home').onclick=home;$('tool-close').onclick=closeTool;$('tool-handle').onclick=closeTool;$('tool-toggle').onclick=()=>{if(!$('tool').hidden){closeTool();return;}const key=lastToolContext===active?.key&&lastTool!=='save'?lastTool:'details';action(key||'details').catch(error);};$('library-back').onclick=()=>active?setActive(active):home();$('collections-open').onclick=()=>chooseArea('collections').catch(error);$('metrics').onclick=()=>openTool('metrics').catch(error);$('help').onclick=()=>openTool('help').catch(error);$('command-open').onclick=palette;
$('sources-start').onclick=()=>chooseArea('sources').catch(error);$('catalog-start').onclick=()=>chooseArea('catalog').catch(error);$('upload-start').onclick=()=>selectPdf();$('pdf-upload').oncancel=()=>{uploadProject=null;};$('pdf-upload').onchange=()=>{const file=$('pdf-upload').files[0];const destination=uploadProject??selectedProject;uploadProject=null;if(file)addFile(file,destination).catch(error);};$('project').onchange=()=>{selectedProject=$('project').value;listSources=true;renderExplorer();if(!$('library').hidden){if(area==='sources')sourceLibrary();else if(area==='catalog')catalogBrowser().catch(error);}status('Contexto para os próximos materiais: '+(projectInfo(selectedProject)?.title||'acervo local')+'. Abas abertas mantêm seu contexto.');};
window.addEventListener('keydown',event=>{if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();palette();}if(event.key==='Escape'&&!$('commands').open){if(!$('tool').hidden)closeTool();else{document.body.classList.remove('focused');$('focus').textContent='Concentrar';}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)clearTimeout(pollTimer);else schedulePoll();});
window.addEventListener('beforeunload',event=>{if(catalogBusy||uploading||[...contexts.values()].some(c=>c.saving||c.dirty||c.passageDirty)||[...panels.values()].some(p=>p.task&&!p.task.canClose()||p.viewerControl?.isSaving())){event.preventDefault();event.returnValue='';}});
async function boot(){
 const started=performance.now(),entry=location.hash;let entryFailed=false;
 const requests=[request('/api/health'),request('/api/editorial/projects'),request('/api/editorial/pdf/sources?light=1'),request('/api/editorial/pdf-pilots')];
 const diagnostics=Promise.allSettled(requests);
 // Document entry does not wait for unrelated PDF inventory/pilot requests.
 if(entry.startsWith('#/')){
  if(new URLSearchParams(entry.split('?')[1]||'').has('projeto')){try{projects=(await requests[1]).items;}catch{}}
  try{await navigate(location.origin+'/editorial'+entry);}catch(value){entryFailed=true;error(value);const notice=node('div',{class:'entry-error',role:'alert',text:'Não foi possível abrir o documento: '+value.message});notice.append(button('Tentar abrir novamente',async()=>{await navigate(location.origin+'/editorial'+entry);notice.remove();}));$('landing').prepend(notice);}
 }
 const result=await diagnostics;
 $('connection').textContent=result[0].status==='fulfilled'?'● Backend local':'○ Backend indisponível';
 if(result[1].status==='fulfilled'){projects=result[1].value.items;const chosen=selectedProject;$('project').replaceChildren(node('option',{value:'',text:'Acervo · sem projeto'}),...projects.filter(p=>!p.archived).map(p=>node('option',{value:p.id,text:p.title})));$('project').value=chosen;}
 if(result[2].status==='fulfilled')sources=result[2].value.items;
 if(result[3].status==='fulfilled')pilots=result[3].value.items;
 renderExplorer();
 if(!active&&!entryFailed)status(result.some(r=>r.status==='rejected')?'Algumas consultas falharam. Use Atualizar ou veja o Diagnóstico.':'Estúdio pronto · '+Math.round(performance.now()-started)+' ms');
 try{$('resume-session').hidden=!sessionStorage.getItem('studio:layout:v2');}catch{}
}
window.addEventListener('hashchange',()=>{if(location.hash.startsWith('#/'))navigate(location.href).catch(error);});
boot().catch(error);
